from taf.ul.kpi_selector.operations.reset_cu.classical_reset_cu.reset_cu_prototype import ResetCu


class ResetCu22R1(ResetCu):
    def get_kpi(self):
        """
        Gets kpi for reset cu operation.
        :return: dictionary with timeout, requirement and operation description for reset cu
        :rtype: dict
        """
        if all(
                [
                    "ASIM" in self.bts.smod_hw_types,
                    "ABIO" in self.bts.bbmod_hw_types,
                    "AEUD" in self.bts.rmod_hw_types,
                    self.bts.cell_technologies == "TDD",
                    self.bts.radio_protocol == "eCPRI",
                    self.bts.number_of_rmods <= 2,
                    self.bts.setup_mode == "NSA"
                ]
        ):
            self.operation_details["Timeout"] = 180
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.12810"

        elif all(
                [
                    "ASIL" in self.bts.smod_hw_types,
                    "ABIO" in self.bts.bbmod_hw_types,
                    "AWEUA" in self.bts.rmod_hw_types,
                    self.bts.number_of_rmods <= 2,
                    self.bts.cell_technologies == "TDD",
                    self.bts.radio_protocol == "eCPRI",
                    self.bts.setup_mode == "NSA"
                ]
        ):
            self.operation_details["Timeout"] = 180
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.12817"

        else:
            return super(ResetCu22R1, self).get_kpi()

        return self.operation_details
